// Generate personalized email content based on lead journey
const items = $input.all();
const emails = [];

const emailTemplates = {
  day1: {
    subject: '🏠 Welcome to Your Mortgage Journey, {{ firstName }}!',
    type: 'welcome',
    priority: 'high'
  },
  day3: {
    subject: 'Your Complete Mortgage Document Checklist',
    type: 'education',
    priority: 'normal'
  },
  day5: {
    subject: "Today's Mortgage Rates + Your Personalized Quote",
    type: 'rate-update',
    priority: 'high'
  },
  day7: {
    subject: '7 Common Mortgage Mistakes (And How to Avoid Them)',
    type: 'education',
    priority: 'normal'
  },
  day10: {
    subject: 'Pre-Approval: Your Secret Weapon in Home Shopping',
    type: 'education',
    priority: 'high'
  },
  day14: {
    subject: '{{ firstName }}, Let\'s Fast-Track Your Approval',
    type: 'milestone',
    priority: 'high'
  },
  day17: {
    subject: 'Success Story: How Sarah Got Approved in 10 Days',
    type: 'social-proof',
    priority: 'normal'
  },
  day21: {
    subject: '⚠️ Rates Alert: Lock In Before They Rise',
    type: 'urgency',
    priority: 'critical'
  },
  day24: {
    subject: 'Your Questions Answered: Mortgage FAQ',
    type: 'education',
    priority: 'normal'
  },
  day28: {
    subject: 'Final Reminder: Special Rate Expires Soon',
    type: 'urgency',
    priority: 'high'
  },
  day30: {
    subject: '{{ firstName }}, We\'re Still Here to Help',
    type: 're-engagement',
    priority: 'high'
  }
};

items.forEach(item => {
  const lead = item.json;
  const day = lead.day_number;
  let template = emailTemplates[`day${day}`];

  // Use closest template if exact day not found
  if (!template) {
    const availableDays = Object.keys(emailTemplates).map(k => parseInt(k.replace('day', '')));
    const closestDay = availableDays.reduce((prev, curr) => 
      Math.abs(curr - day) < Math.abs(prev - day) ? curr : prev
    );
    template = emailTemplates[`day${closestDay}`];
  }

  if (template) {
    // Personalize subject line
    const subject = template.subject
      .replace('{{ firstName }}', lead.first_name)
      .replace('{{ lastName }}', lead.last_name);

    emails.push({
      json: {
        leadId: lead.id,
        firstName: lead.first_name,
        lastName: lead.last_name,
        email: lead.email,
        phone: lead.phone,
        dayNumber: day,
        subject: subject,
        templateType: template.type,
        priority: template.priority,
        leadScore: lead.lead_score,
        propertyValue: lead.property_value,
        loanAmount: lead.loan_amount,
        emailOpenCount: lead.email_open_count || 0,
        emailClickCount: lead.email_click_count || 0
      }
    });
  }
});

return emails;
